"""Capture the actual prior review fixture; never edits its source workspace."""
import hashlib
import json
from pathlib import Path
import sys

origin = Path(sys.argv[1])
output = Path(__file__).with_name('review-data.json')
paths = {
 'proposal': ('proposal/v01/proposal.md', 'Frozen proposal v01', 'Submitted claim'),
 'experiments': ('proposal/v01/experiments.md', 'Original experiment plan', 'Planned / conditional'),
 'evidence': ('proposal/v01/evidence.md', 'Evidence inventory', 'Evidence boundaries'),
 'report': ('final/final_report.md', 'Final research report', 'Final synthesis'),
 'issues': ('issue_tracker.md', 'Original issue tracker', 'Verified dispositions'),
 'rebuttal': ('rebuttals/round-01.md', 'Author rebuttal', 'Author response'),
 'ac': ('reviews/round-01/ac-meta-review.md', 'AC meta-review', 'Chair synthesis'),
 'sac': ('reviews/round-01/sac-assessment.md', 'Independent SAC assessment', 'Process audit / analytical finding'),
 'discussion-before': ('reviews/round-01/discussion-before-rebuttal.md', 'Pre-rebuttal discussion', 'Actual reviewer exchange'),
 'discussion-after': ('reviews/round-01/discussion-after-rebuttal.md', 'Post-rebuttal discussion', 'Actual reviewer exchange'),
 'scores': ('reviews/score-history.md', 'Reviewer score history', 'Unofficial internal rubric'),
 'search-log': ('literature/search_log.md', 'Literature search limitations', 'Unavailable external evidence'),
}
for number in (1,2,3):
 for phase in ('initial','final'):
  paths[f'{phase}-r{number}'] = (f'reviews/round-01/reviewer-R{number}-{phase}.md', f'R{number} {phase} review', 'Independent reviewer judgment')
sources = {}
for key,(path,title,kind) in paths.items():
 raw = (origin/path).read_bytes()
 sources[key] = dict(id=key,path=path,title=title,kind=kind,text=raw.decode(),sha256=hashlib.sha256(raw).hexdigest())
issues = [
 dict(id='R01-R1-01', title='Absolute value is not the stated projection', shortTitle='Exactness fails', severity='Critical', status='Open', aliases=['R01-R1-01','R01-R2-01','R01-R3-01'], concern='For every negative input, zero is feasible and closer than abs(x). At x = −1, the proposed operator incurs objective 4; zero incurs 1. The exact projection is max(x, 0).', response='Accepted. Withdraw H01 and stop this formulation. The author did not replace or edit frozen v01.', reassessment='Withdrawal acknowledges the counterexample; it does not repair the reviewed method. All three reviewers retain their unfavorable recommendation.', criterion='Withdraw H01. Any substantive repair must be submitted as a new formulation and independently reviewed.', sources=['initial-r2','rebuttal','final-r2','sac']),
 dict(id='R01-R1-02', title='Unrestricted optimizer compatibility fails', shortTitle='Drop-in claim fails', severity='Major', status='Open', aliases=['R01-R1-02','R01-R2-02','R01-R3-02'], concern='For f(z) = (z + 1)² / 2, a gradient step of size one gives −1. Exact projection reaches the constrained optimum zero; absolute value remains at one.', response='Accepted. Withdraw unrestricted H03. A different absolute-value algorithm would be a new proposal, outside this review.', reassessment='The step equals reciprocal curvature, so the example does not depend on an oversized step. The defect remains in unchanged v01; this does not rule out every possible use of absolute value.', criterion='Withdraw unrestricted H03. Any alternative algorithm needs its own specification and justified convergence conditions.', sources=['initial-r2','discussion-before','rebuttal','final-r2','ac']),
 dict(id='R01-R1-03', title='Novelty and research significance remain unassessed', shortTitle='Novelty unknown', severity='Moderate', status='Open', aliases=['R01-R1-03'], concern='No external literature was supplied or retrieved. Closest prior work, research novelty, and a meaningful workload bottleneck are not established.', response='Accepted as uncertainty, not proof of nonnovelty. Preserve the gap; even verified novelty would not repair the correctness contradiction.', reassessment='Unknown novelty and runtime are distinct from falsified correctness. No negative novelty finding or current coverage is claimed.', criterion='For any future revised idea, inspect verified closest sources and establish a meaningful workload and contribution.', sources=['initial-r1','search-log','rebuttal','final-r1','sac']),
 dict(id='R01-R2-03', title='Speed reporting corrected; runtime remains unknown', shortTitle='Speed unmeasured', severity='Moderate', status='Resolved', aliases=['R01-R2-03'], concern='No device, dtype, implementation, or measurements support the speed claim. Faster execution cannot establish equivalence of different operators.', response='Keep H02 untested. Cancel conditional E02 and E03 after the correctness gate fails. Do not report an empirical improvement.', reassessment='The reporting/action criterion is met. This resolution does not establish runtime, repair the method, or change the Kill recommendation.', criterion='Keep speed untested and cancel conditional benchmarks for this failed formulation.', sources=['initial-r2','rebuttal','final-r2','ac','sac'])
]
project = dict(slug='faster-nonnegative-projection',title='Faster nonnegative projection',version='v01',stage='Proposal',mode='Independent model-agent review',round=1,maxRounds=1,convergence='Not converged',decision='Kill',summary='Replace exact nonnegative projection with absolute value to reduce projection cost in constrained optimization.',rationale='The central exactness claim is false. A negative input is enough to disprove the proposed method; a separate optimizer counterexample defeats unrestricted drop-in compatibility.',novelty='Not assessed',runtime='Unmeasured',sourceDate='07 Nov 2026',largestRisk='The reviewed operator is mathematically invalid for negative inputs.',nextAction='Stop this formulation. Preserve the counterexamples and review record; do not run the canceled benchmarks.',sourceCoverage='Supplied claim and exact reasoning only. Offline review; external novelty and runtime are unassessed.')
claims = [dict(id='H01',title='Exact projection',text='P(x) = abs(x) minimizes (z − x)² over z ≥ 0 for every real x.',status='Falsified by exact reasoning',sources=['proposal','initial-r2','sac']),dict(id='H02',title='Lower execution cost',text='Absolute value may execute faster than the exact projection.',status='Unmeasured',sources=['proposal','evidence','rebuttal']),dict(id='H03',title='Drop-in optimizer use',text='The operator can replace exact projection in constrained optimization without qualification.',status='Unrestricted claim falsified',sources=['proposal','initial-r2','sac'])]
timeline = [dict(id='submission',label='Submission',role='Author',summary='Frozen v01; exactness and drop-in claims submitted as hypotheses.',source='proposal'),dict(id='reviews',label='Independent reviews',role='R1 · R2 · R3',summary='All three reviewers identify the correctness failure; significance coverage is retained.',source='scores'),dict(id='discussion',label='AC discussion',role='AC + reviewers',summary='Check the step-size objection and separate falsification from unknown novelty.',source='discussion-before'),dict(id='rebuttal',label='Author rebuttal',role='Author',summary='Accept the counterexamples; withdraw H01 and unrestricted H03 without rewriting v01.',source='rebuttal'),dict(id='reassessment',label='Reassessment',role='R1 · R2 · R3',summary='All overall scores remain 1/10. Withdrawal does not repair the method.',source='discussion-after'),dict(id='chairs',label='Chair assessment',role='AC + separate SAC',summary='Both independently recommend Kill. SAC verifies the frozen packet hashes.',source='sac')]
experiments = [dict(id='E01',title='Exact scalar correctness gate',kind='Analytical finding',status='Failed by proof',summary='At x = −1, abs(x) yields squared distance 4; feasible zero yields 1. No empirical run is needed to falsify a universal claim.',source='initial-r2'),dict(id='E02',title='Matched speed benchmark',kind='Conditional planned experiment',status='Canceled',summary='Not executed after E01 fails. Hardware timing remains unknown.',source='experiments'),dict(id='E03',title='Optimizer comparison',kind='Conditional planned experiment',status='Canceled',summary='The empirical check was canceled. The separate exact quadratic counterexample is analytical evidence, not an empirical run.',source='rebuttal')]
reviewers = [dict(id=f'R{i}',focus=focus,initial=1,final=1,confidence='5/5 for algebra only',reason='Withdrawal acknowledges but does not repair frozen v01.',sources=[f'initial-r{i}',f'final-r{i}']) for i,focus in [(1,'Novelty + significance'),(2,'Technical soundness'),(3,'Experimental rigor + significance')]]
targets = {'decision':dict(title='Final decision and investment rationale',sources=['report','sac']), 'review-history':dict(title='Round 01 review history',sources=['scores','discussion-before','discussion-after']), 'experiments':dict(title='Experiment plan and evidence boundary',sources=['experiments','evidence'])}
for item in issues+claims:
 targets[item['id']] = dict(title=item.get('title'),sources=item['sources'])
output.write_text(json.dumps(dict(project=project,issues=issues,claims=claims,timeline=timeline,experiments=experiments,reviewers=reviewers,sources=sources,targets=targets),ensure_ascii=False,indent=2)+'\n')
print(f'Captured {len(sources)} unchanged sources into {output.name}.')
